import React, { ReactElement } from 'react';

import { ViewIcon, ViewOffIcon } from '@dynatrace/strato-icons';

import {
  coloredEyeOffIcon,
  eyeIcon,
  singleDimensionIcon,
} from './ChartLegendIcon.sty.js';

interface LegendIconProps {
  visible: boolean;
  hover: boolean;
  disabled: boolean;
  color: string;
  icon?: ReactElement;
}

export const ChartLegendIcon = ({
  visible,
  hover,
  disabled,
  color,
  icon,
}: LegendIconProps) => {
  const withCustomIconOrDefault = icon ? (
    icon
  ) : (
    <span
      data-testid="chart-legend-item-icon-visible"
      className={singleDimensionIcon}
      style={{ backgroundColor: color }}
    />
  );

  const iconVisibleOrHidden = visible ? (
    withCustomIconOrDefault
  ) : (
    <ViewOffIcon
      data-testid="chart-legend-item-icon-hidden"
      size="small"
      className={coloredEyeOffIcon}
      style={{ color }}
    />
  );

  return hover && visible && !disabled ? (
    <ViewIcon
      data-testid="chart-legend-item-icon-hover"
      size="small"
      className={eyeIcon}
    />
  ) : (
    iconVisibleOrHidden
  );
};
